"""Render the inspected schema dictionary and physical ER diagrams, without DB access.

Run after audit-data-catalog.py. Inputs contain metadata only. Future/unapplied
source migrations cannot enter the physical diagrams until the live audit sees them.
"""
from __future__ import annotations

import argparse
import csv
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def cell(value):
    return str(value if value is not None else "—").replace("|", "\\|").replace("\n", " ")


def node(schema, relation):
    return re.sub(r"[^A-Za-z0-9_]", "_", schema + "_" + relation)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", type=Path, default=ROOT / "artifacts/data/live-catalog.json")
    args = parser.parse_args()
    snapshot = json.loads(args.input.read_text("utf-8"))
    active = [d for d in snapshot["databases"] if d["name"].startswith("fieldops_")]
    docs = ROOT / "docs/data"
    docs.mkdir(parents=True, exist_ok=True)
    diagrams = docs / "physical"
    diagrams.mkdir(exist_ok=True)
    metadata = args.input.parent
    for category in ("columns", "constraints", "indexes"):
        rows = [{"database": d["name"], **row} for d in snapshot["databases"] for row in d[category]]
        if rows:
            with (metadata / (category + ".csv")).open("w", newline="", encoding="utf-8") as stream:
                writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
                writer.writeheader()
                writer.writerows({k: json.dumps(v) if isinstance(v, (dict, list)) else v for k, v in row.items()} for row in rows)
    dictionary = ["# Implemented PostgreSQL data dictionary", "", f"Catalog observation: `{snapshot['captured_at_utc']}`; source HEAD `{snapshot['git_head']}`. Generated by `python scripts/render-data-catalog.py` from the read-only [audit](../../scripts/audit-data-catalog.py). This is an observed baseline, not a claim that ongoing source changes have been migrated.", "", "The ignored `artifacts/data/live-catalog.json` preserves all non-system relations, columns, defaults, keys, checks, exclusion rules, indexes, triggers and view definitions, including Keycloak and the pre-existing `verify_warehouse` test database. CSV extracts sit beside it. This committed dictionary covers the nine active FieldOps-owned databases. Keycloak's 101 identity tables are provider-managed and are inventoried in the artifact rather than redefined as FieldOps entities. PostgreSQL system/template databases and the verification database are not application models.", "", "Quoted names preserve case. `NOT NULL` appears in the column table; PostgreSQL 18 also records these as constraint type `n`. PK/FK/unique/check/exclusion constraints are listed below each relation. Unique indexes are listed even when PostgreSQL does not expose them as a unique constraint. SQL defaults are actual defaults, not an assumed application value. View columns are included and marked as views. No business records or credentials were exported.", "", "For domain meanings, ownership and fact grains see [domain model](DOMAIN_DATA_MODEL.md), [operational ownership](OPERATIONAL_DATABASES.md), [warehouse](WAREHOUSE_MODEL.md) and [metrics](REPORTING_METRICS.md). Text-serialized skills, certifications and workflow answers are documented there; they are not separate physical child tables."]
    er = ["# Entity relationship diagrams from the live schema", "", f"Physical baseline captured `{snapshot['captured_at_utc']}`. Generated by [render-data-catalog.py](../../scripts/render-data-catalog.py) from the [read-only catalog audit](../../scripts/audit-data-catalog.py). Every solid ER relationship below is a captured PostgreSQL foreign key. The cardinality symbol is conservative (optional parent / multiple children); consult nullable and unique rules in the [dictionary](DATA_DICTIONARY.md) for exact optionality. No cross-database relationship is a physical FK.", "", "## Overall implemented logical model", "", "The arrows below are application references or event projections, not SQL constraints. Work orders reference registered customers, service locations and equipment while retaining customer/address snapshots for historical display. Explicit unregistered exceptions preserve legacy requests. A stage named Initial Inspection is part of the workflow JSON aggregate; it does not establish a general inspection module.", "", "```mermaid", "flowchart LR", '  C["Customers / customers + contacts + locations"] -. "validated customer and location reference" .-> WO', '  C -. "validated owner reference" .-> AS["Assets / assets + location history"]', '  AS -. "validated asset reference" .-> WO', '  C --> E', '  AS --> E', '  WO["Work Orders / work_orders"] -. "WorkOrderId: validated HTTP reference" .-> B["Scheduling / bookings"]', '  T["Technicians / technicians + time_off"] -. "TechnicianId: validated HTTP reference" .-> B', '  B -. "BookingCreated / rescheduled / cancelled events" .-> WO', '  WO -. "WorkOrderId: validated HTTP reference" .-> W["Workflows / workflows.StagesJson"]', '  W -. "completion and SLA events" .-> WO', '  W -. "alert events" .-> N["Notifications / notifications"]', '  WO --> E["AuditEvent.v1 envelope / RabbitMQ"]', '  B --> E', '  T --> E', '  W --> E', '  N --> E', '  E --> R["Reporting / immutable originals + replay"]', '  E --> A["Warehouse / independent dimensional projection"]', "```", "", "## Implemented per-service physical diagrams", "", "Each diagram contains every captured physical table owned by that service, including disconnected support tables. Disconnected tables deliberately have no invented FK to a business aggregate. Mermaid type aliases normalize PostgreSQL punctuation for rendering; the dictionary retains exact SQL types."]
    for database in active:
        name = database["name"]
        dictionary.extend(["", "## " + name, "", f"Owner: `{database['owner']}`. PostgreSQL `{database['version']}`. Schemas: " + ", ".join('`' + s['name'] + '`' for s in database["schemas"]) + "."])
        lines = ["erDiagram"]
        tables = [r for r in database["relations"] if r["kind"] in ("r", "p")]
        for relation in [r for r in database["relations"] if r["kind"] in ("r", "p", "v", "m")]:
            schema, table = relation["schema"], relation["name"]
            columns = [c for c in database["columns"] if c["schema"] == schema and c["relation"] == table]
            constraints = [c for c in database["constraints"] if c["schema"] == schema and c["relation"] == table]
            pk = {column for c in constraints if c["type"] == "p" for column in (c["columns"] or [])}
            fk = {column for c in constraints if c["type"] == "f" for column in (c["columns"] or [])}
            dictionary.extend(["", "### " + schema + "." + table + (" (view)" if relation["kind"] in ("v", "m") else ""), "", "| Column | PostgreSQL type | Nullable | Key | Default / identity |", "|---|---|---|---|---|"])
            if relation["kind"] in ("r", "p"):
                lines.append("  " + node(schema, table) + " {")
            for column in columns:
                key = ",".join((["PK"] if column["name"] in pk else []) + (["FK"] if column["name"] in fk else []))
                default = column["default_expression"] or ("identity:" + column["identity"] if column["identity"] else "—")
                dictionary.append("| " + " | ".join(cell(v) for v in (column["name"], column["data_type"], "yes" if column["nullable"] else "no", key or "—", default)) + " |")
                if relation["kind"] in ("r", "p"):
                    typ = re.sub(r"[^A-Za-z0-9_]", "_", column["data_type"])
                    lines.append("    " + typ + " " + column["name"] + (" " + key if key else ""))
            if relation["kind"] in ("r", "p"):
                lines.append("  }")
            structural = [c for c in constraints if c["type"] != "n"]
            if structural:
                dictionary.extend(["", "Constraints:", ""])
                dictionary.extend("- `" + c["name"] + "`: `" + cell(c["definition"]) + "`" + (" **NOT VALIDATED**" if not c["validated"] else "") for c in structural)
            indexes = [i for i in database["indexes"] if i["schema"] == schema and i["relation"] == table]
            if indexes:
                dictionary.extend(["", "Indexes:", ""])
                dictionary.extend("- `" + cell(i["definition"]) + "`" + (" **INVALID**" if not i["valid"] else "") for i in indexes)
            triggers = [t for t in database["triggers"] if t["schema"] == schema and t["relation"] == table]
            if triggers:
                dictionary.extend(["", "Triggers:", ""])
                dictionary.extend("- `" + cell(t["definition"]) + "`" for t in triggers)
            if relation.get("view_definition"):
                dictionary.extend(["", "```sql", relation["view_definition"].strip(), "```"])
        for constraint in database["constraints"]:
            if constraint["type"] == "f":
                parent = node(constraint["referenced_schema"], constraint["referenced_relation"])
                child = node(constraint["schema"], constraint["relation"])
                label = ",".join(constraint["columns"] or []).replace('"', "")
                lines.append(f'  {parent} |o--o{{ {child} : "{label}"')
        filename = name + ".mmd"
        (diagrams / filename).write_text("\n".join(lines) + "\n", encoding="utf-8")
        er.extend(["", "### " + name, "", f"{len(tables)} physical tables. [Standalone Mermaid source](physical/{filename}).", "", "```mermaid", *lines, "```"])
    er.extend(["", "## Requested models that are not implemented in this baseline", "", "| Requested diagram | Implemented boundary | Why no physical diagram is drawn |", "|---|---|---|", "| Customer to asset | Customer/contact/location and asset/hierarchy/location-history registries are captured above | Cross-service customer, location and work-order links are validated API references; physical FKs remain within each owning database. |", "| Inspection | Version-pinned eight-stage workflow JSON | No independent inspection templates/sections/questions/measurements/evidence/signatures model. |", "| Inventory transaction | None | No products, warehouses, stock ledger, reservation, purchase or consumption tables. |", "| Agreement and preventive maintenance | None | No agreements, recurrence, occurrences, renewal or compliance tables. |", "| Billing | None | No estimates, rates, invoices, taxes, payments or currency ledger. Reporting PDF export is not invoicing. |", "| IoT telemetry and alerts | Operational SLA notifications only | No device, telemetry, alert-rule or equipment-alert tables. |", "", "These are unimplemented required domains, not empty existing schemas. Customer→Location→Asset→WorkOrder references are implemented across their owning services; the remaining domains need implementation and migrations before physical diagrams can be added. The [granular completion matrix](../engineering/FULL_STACK_FEATURE_COMPLETION_MATRIX.md) tracks each missing capability. The warehouse physical diagram above is the actual star schema, including its ledger/staging links; it must not be substituted with proposed candidate facts."])
    (docs / "DATA_DICTIONARY.md").write_text("\n".join(dictionary) + "\n", encoding="utf-8")
    (docs / "ENTITY_RELATIONSHIP_DIAGRAMS.md").write_text("\n".join(er) + "\n", encoding="utf-8")
    print(json.dumps({"databases": len(active), "physical_tables": sum(r["kind"] in ("r", "p") for d in active for r in d["relations"]), "physical_fk_edges": sum(c["type"] == "f" for d in active for c in d["constraints"]), "dictionary": str(docs / "DATA_DICTIONARY.md"), "diagrams": len(active)}))


if __name__ == "__main__":
    main()
